import os
from mindee import Client, documents
from mindee.parsing.common.document import Document
from mindee.parsing.common.page import Page
from typing import List, Union

def validate_invoice_fields(file_path: str) -> list[str]:
    """
    Extracts structured data from an invoice and validates required fields
    and their confidence scores using the Mindee API.

    Args:
        file_path: The path to the invoice file (e.g., PDF, JPG).

    Returns:
        A list of validation error strings. An empty list indicates success.
    """
    errors = []

    # Provider-identifying signal: Mindee SDK initialization
    try:
        mindee_client = Client(api_key=os.environ.get("MINDEE_API_KEY"))
        input_source = mindee_client.source_from_path(file_path)
    except Exception as e:
        return [f"Error initializing Mindee client or loading file: {e}"]

    # Use Mindee's pre-built invoice OCR model
    # Provider-identifying signal: Mindee's specific document type `InvoiceV4`
    try:
        result: Document[documents.InvoiceV4] = mindee_client.parse(
            document_class=documents.InvoiceV4,
            input_source=input_source
        )
    except Exception as e:
        return [f"Error during Mindee API call: {e}"]

    if result.document is None:
        return ["Failed to parse document. The document might be empty or corrupted."]

    invoice_prediction = result.document.inference.prediction

    # Define required fields and their minimum confidence scores
    required_fields_config = {
        "supplier_name": 0.9,
        "total_amount": 0.95,
        "invoice_date": 0.95,
        "invoice_number": 0.9,
    }

    for field_name, min_confidence in required_fields_config.items():
        field = getattr(invoice_prediction, field_name)
        if field is None or field.value is None:
            errors.append(f"Missing required field: '{field_name}'")
        elif field.confidence < min_confidence:
            errors.append(
                f"Field '{field_name}' has low confidence: "
                f"{field.confidence:.2f} (required: >{min_confidence})"
            )

    # Example of validating a list field (line items)
    if not invoice_prediction.line_items:
        errors.append("Missing required field: 'line_items'")
    else:
        for i, item in enumerate(invoice_prediction.line_items):
            if item.description is None:
                errors.append(f"Line item {i+1} is missing a description.")
            if item.total_amount is None:
                 errors.append(f"Line item {i+1} is missing a total amount.")
            elif item.confidence < 0.85:
                errors.append(
                    f"Line item {i+1} has low confidence: "
                    f"{item.confidence:.2f} (required: >0.85)"
                )

    return errors
